SELECT id, user_id, resource_id, client_request_id, start_at, end_at, accepted_at,
       arrival_deadline, status, cancel_reason, check_in_at, check_out_at, created_at, updated_at
FROM reservation
WHERE user_id = #{userId}
  AND client_request_id = #{clientRequestId}

SELECT id, user_id, resource_id, client_request_id, start_at, end_at, accepted_at,
       arrival_deadline, status, cancel_reason, check_in_at, check_out_at, created_at, updated_at
FROM reservation
WHERE user_id = #{userId}
  AND client_request_id = #{clientRequestId}
FOR UPDATE

SELECT id, user_id, resource_id, client_request_id, start_at, end_at, accepted_at,
       arrival_deadline, status, cancel_reason, check_in_at, check_out_at, created_at, updated_at
FROM reservation
WHERE resource_id = #{resourceId}
  AND status IN ('RESERVED', 'CHECKED_IN')
  AND start_at < #{end}
  AND end_at > #{start}
ORDER BY id
FOR UPDATE

SELECT COUNT(*)
FROM reservation res
WHERE res.user_id = #{userId}

    AND res.status = #{status}


    AND res.start_at >= #{from}


    AND res.start_at < #{to}

SELECT
,
r.name AS resource_name,
r.resource_type,
r.location,
r.unit_label
FROM reservation res
JOIN resource r ON r.id = res.resource_id
WHERE res.user_id = #{userId}

    AND res.status = #{status}


    AND res.start_at >= #{from}


    AND res.start_at < #{to}

ORDER BY res.start_at DESC, res.id DESC
LIMIT #{size} OFFSET #{offset}
